@require_http_methods(["POST"])
def purge_backup_snapshot(request, snapshot_id):
    snapshot = get_object_or_404(DatabaseSnapshot, id=snapshot_id, account=request.user.account)
    delete_s3_snapshot_task.delay(storage_key=snapshot.s3_key)
    snapshot.delete()
    return JsonResponse({'status': 'snapshot purge scheduled'})
